// Daily L1 nurture pass: (1) sync approvals from decisions tasks, (2) queue due touches 2-4,
// (3) emit approved sends for delivery. Cadence: touch N due 3 days after touch N-1 sent.
// Every read and write runs in an HTTP Request node on the stored Supabase
// credential, one request each. "Plan Touches" used to make them itself, row by
// row, with the service-role key written into its source (moved 2026-10-03).
//
// 1. approval sync: queued rows whose task is done -> approved; dropped/superseded -> rejected
const fetched = $input.first().json.body;
const queued = Array.isArray(fetched) ? fetched : [];
const taskIds = [...new Set(queued.filter(r => r.approval_task_id).map(r => r.approval_task_id))];
// An empty list reads nothing: tasks.id is the primary key, never null.
const filter = taskIds.length ? 'in.(' + taskIds.map(id => JSON.stringify(String(id))).join(',') + ')' : 'is.null';
return [{ json: { queued, url: 'https://gojpffsrxybbpbdzzrvs.supabase.co/rest/v1/tasks?select=id,status&id=' + encodeURIComponent(filter) } }];

// Decides each queued row from its approval task, as before. "Mark approved"
// and "Mark rejected" write the two lists, one PATCH each.
const queued = $('Plan approval reads').first().json.queued;
const fetched = $input.first().json.body;
const tasks = Array.isArray(fetched) ? fetched : [];
const statusById = new Map(tasks.map(t => [t.id, t.status]));
const approve = [];
const reject = [];
for (const row of queued) {
  if (!row.approval_task_id) continue;
  const st = statusById.get(row.approval_task_id) || '';
  if (st === 'done') approve.push(row.id);
  else if (st === 'superseded' || st === 'dropped') reject.push(row.id);
}
// An empty list matches no row: acquisition_sends.id is the primary key.
const ids = list => list.length ? 'in.(' + list.join(',') + ')' : 'is.null';
const base = 'https://gojpffsrxybbpbdzzrvs.supabase.co/rest/v1/acquisition_sends?id=';
return [{ json: { approve_url: base + ids(approve), reject_url: base + ids(reject), approvals_synced: approve.length, rejected: reject.length } }];

// 2. queue due touches: last sent touch per active lead, +3 days
const now = Date.now();
const fetched = $input.first().json.body;
const sentRows = Array.isArray(fetched) ? fetched : [];
const byLead = {};
for (const r of sentRows) { (byLead[r.lead_id] = byLead[r.lead_id] || []).push(r); }
const due = [];
for (const [leadId, rows] of Object.entries(byLead)) {
  const maxTouch = Math.max(...rows.map(r => r.touch_number));
  if (maxTouch >= 4) continue;
  if (rows.some(r => ['queued','approved','rejected','suppressed','failed'].includes(r.status) && r.touch_number === maxTouch)) continue;
  const last = rows.find(r => r.touch_number === maxTouch);
  if (!last || last.status !== 'sent' || !last.sent_at) continue;
  if (now - new Date(last.sent_at).getTime() < 3 * 86400000) continue;
  due.push({ leadId, n: maxTouch + 1 });
}
// "Fetch due leads" reads every due lead in one request.
const filter = due.length ? 'in.(' + due.map(d => d.leadId).join(',') + ')' : 'is.null';
return [{ json: { due, url: 'https://gojpffsrxybbpbdzzrvs.supabase.co/rest/v1/leads?select=id,email,churned_at&id=' + filter } }];

// Renders each due touch and its approval task. Both get their ids here, so
// "Insert touches" and "Insert approval tasks" can each write every row in one
// request: the send carries approval_task_id from the start instead of being
// patched with it afterwards.
const FRAME = {"1":{"subject":"Your {artifact_name} is inside","body":"Here is your {artifact_name}. No signup wall, it is just yours.\n\nOne thing worth doing while you have it open: CTRL can build a portable context file of you in about 2 minutes. Paste it into ChatGPT or Claude and the next answer you get is about you, your company, your priorities. Not generic advice.\n\nThat part is free and takes less time than reading this email twice.\n\nBuild your context file: https://ctrl.themindmaker.ai?utm_campaign=mm_ctrl_nurture_v1&utm_source=nurture&utm_medium=email"},"2":{"subject":"You re-explain yourself to AI every day","body":"Count how many times you told an AI tool who you are this week. Your role, your company, what you are working on. Every conversation starts from zero, so every answer stays generic. That is the zero-context tax, and leaders pay it daily.\n\nCTRL ends it. Two minutes of talking builds your Memory Web. One click exports it to any AI tool you already use.\n\nIf you have not built yours yet, it is free: https://ctrl.themindmaker.ai?utm_campaign=mm_ctrl_nurture_v1&utm_source=nurture&utm_medium=email"},"3":{"subject":"What your context file is not telling you","body":"The free Memory Web tells your AI tools who you are. The Full Diagnostic tells you what you are not seeing: the tensions in how you are operating, the risks you are discounting, and the scenarios worth pressure-testing before they arrive.\n\nIt runs on the context you already built, so it is specific to your situation, not a template. One-time, $49, yours to keep.\n\nRun your Full Diagnostic: https://ctrl.themindmaker.ai?utm_campaign=mm_ctrl_nurture_v1&utm_source=nurture&utm_medium=email"},"4":{"subject":"Last note from us","body":"This is the last email in this series, so the short version:\n\nYou built your context file. The Full Diagnostic is the deep read on it: tensions, risks, scenarios, the complete thinking tools. $49 once. If the free version was useful, this is the part leaders tell us was worth paying for.\n\nEither way, we stop emailing you after this.\n\nRun the Diagnostic: https://ctrl.themindmaker.ai?utm_campaign=mm_ctrl_nurture_v1&utm_source=nurture&utm_medium=email"}};
const FOOTER = "\n\n---\nCTRL by Mindmaker. You received this because you requested an artifact at ctrl.themindmaker.ai.\nUnsubscribe: https://krishraja10101.app.n8n.cloud/webhook/ctrl-unsub?e={email}";
function uuidv4() {
  if (globalThis.crypto && typeof globalThis.crypto.randomUUID === 'function') return globalThis.crypto.randomUUID();
  const h = Array.from({ length: 32 }, () => Math.floor(Math.random() * 16).toString(16));
  h[12] = '4';
  h[16] = ((parseInt(h[16], 16) & 0x3) | 0x8).toString(16);
  const s = h.join('');
  return `${s.slice(0, 8)}-${s.slice(8, 12)}-${s.slice(12, 16)}-${s.slice(16, 20)}-${s.slice(20)}`;
}
const due = $('Plan due touches').first().json.due;
const fetched = $input.first().json.body;
const leadById = new Map((Array.isArray(fetched) ? fetched : []).map(l => [l.id, l]));
let suppressed_skips = 0;
const sends = [];
const tasks = [];
for (const { leadId, n } of due) {
  const lead = leadById.get(leadId);
  if (!lead || lead.churned_at) { suppressed_skips++; continue; }
  const subject = FRAME[n].subject;
  const bodyTxt = FRAME[n].body + FOOTER.replace('{email}', encodeURIComponent(lead.email));
  const sendId = uuidv4();
  const taskId = 'send-' + sendId;
  sends.push({ id: sendId, lead_id: leadId, lane: 'mm_ctrl', touch_number: n, rendered_subject: subject, rendered_body: bodyTxt, status: 'queued', approval_task_id: taskId });
  tasks.push({ id: taskId, title: 'L1 approve: CTRL nurture touch ' + n + ' to ' + lead.email, description: 'Approved frame mm_ctrl_nurture_v1, touch ' + n + '. Mark done to send on the next scheduler pass; supersede to reject.\n\nSubject: ' + subject + '\n\n' + bodyTxt.slice(0, 1200), agent: 'cleo', status: 'waiting', workstream: 'acquisition' });
}
return [{ json: { sends, tasks, suppressed_skips } }];

// A touch already queued for that lead is skipped by the insert (the unique key
// on lead, frame and touch), as the old catch did. Only touches that went in
// get an approval task.
const built = $('Build touches').first().json;
const res = $input.first().json;
const inserted = res.statusCode >= 200 && res.statusCode < 300 && Array.isArray(res.body) ? res.body : [];
const insertedTaskIds = new Set(inserted.map(r => r.approval_task_id));
return [{ json: { tasks: built.tasks.filter(t => insertedTaskIds.has(t.id)) } }];

// 3. emit approved sends. "Mark suppressed" writes the suppressed list in one PATCH.
const fetched = $input.first().json.body;
const approved = Array.isArray(fetched) ? fetched : [];
const suppress = [];
const sends = [];
for (const r of approved) {
  const em = r.leads && r.leads.email;
  if (!em || (r.leads && r.leads.churned_at)) { suppress.push(r.id); continue; }
  sends.push({ send_id: r.id, email: em, subject: r.rendered_subject, bodyTxt: r.rendered_body, touch: r.touch_number });
}
const filter = suppress.length ? 'in.(' + suppress.join(',') + ')' : 'is.null';
return [{ json: { sends, url: 'https://gojpffsrxybbpbdzzrvs.supabase.co/rest/v1/acquisition_sends?id=' + filter } }];

// The day's digest and the approved sends: the same output this node always
// returned. The reads and writes ran in the nodes before it.
const sync = $('Sync approvals').first().json;
const built = $('Build touches').first().json;
const planned = $('Plan approval tasks').first().json.tasks;
const taskRes = $('Insert approval tasks').first().json;
const queuedOk = taskRes.statusCode >= 200 && taskRes.statusCode < 300 ? planned.length : 0;
const sends = $('Plan sends').first().json.sends;
const digest = { approvals_synced: sync.approvals_synced, queued: queuedOk, sending: sends.length, rejected: sync.rejected, suppressed_skips: built.suppressed_skips };
return [{ json: { digest, sends } }];
